<?php
namespace App\Filament\Resources\Assets\RelationManagers;use Filament\Actions\CreateAction;use Filament\Actions\EditAction;use Filament\Forms\Components\DatePicker;use Filament\Forms\Components\TextInput;use Filament\Resources\RelationManagers\RelationManager;use Filament\Schemas\Schema;use Filament\Tables\Columns\TextColumn;use Filament\Tables\Table;
class AssetInsurancesRelationManager extends RelationManager {protected static string $relationship='insurances';protected static ?string $title='Ασφαλίσεις';public function form(Schema $s):Schema{return $s->components([TextInput::make('company')->label('Ασφαλιστική εταιρεία')->required(),TextInput::make('policy_number')->label('Αριθμός συμβολαίου')->required(),TextInput::make('insured_value')->label('Ασφαλιζόμενη αξία')->numeric()->suffix('€')->required(),DatePicker::make('starts_at')->label('Έναρξη')->required(),DatePicker::make('expires_at')->label('Λήξη')->required()]);}public function table(Table $t):Table{return $t->columns([TextColumn::make('company')->label('Εταιρεία'),TextColumn::make('policy_number')->label('Συμβόλαιο'),TextColumn::make('insured_value')->label('Αξία')->money('EUR'),TextColumn::make('expires_at')->label('Λήξη')->date('d/m/Y')])->headerActions([CreateAction::make()->label('Νέο ασφαλιστήριο')])->recordActions([EditAction::make()]);}}
